const q = $input.first().json.query || {};
const token = (q.token || '').trim();
if (!token || token.length < 12 || token.length > 64) {
  return [{ json: { _error: 'TOKEN_INVALID', _status: 400, _details: 'Se requiere ?token=... (12-64 chars)' } }];
}
return [{ json: { token, request_id: 'req_' + Math.random().toString(36).slice(2, 10) } }];

const rows = $input.all().map(i => i.json).filter(r => r && r.id);
const sess = $('Validate Token').first().json;
if (rows.length === 0) {
  return [{ json: { _error: 'PROPOSAL_NOT_FOUND', _status: 404, _details: 'Token desconocido o expirado', request_id: sess.request_id }}];
}
const p = rows[0];
const now = Date.now();
const exp = p.public_token_expires_at ? new Date(p.public_token_expires_at).getTime() : null;
if (exp && now > exp) {
  return [{ json: { _error: 'TOKEN_EXPIRED', _status: 410, _details: 'El enlace ha expirado', expired_at: p.public_token_expires_at, request_id: sess.request_id }}];
}
return [{ json: {
  data: {
    proposal: {
      id: p.id,
      version: p.version,
      title: p.title,
      executive_summary: p.executive_summary,
      scope_description: p.scope_description,
      phases: p.phases || [],
      total_price: p.total_price,
      price_breakdown: p.price_breakdown || [],
      inclusions: p.inclusions || [],
      exclusions: p.exclusions || [],
      optional_items: p.optional_items || [],
      payment_conditions: p.payment_conditions,
      validity_days: p.validity_days,
      estimated_duration: p.estimated_duration,
      warnings: p.warnings || [],
      status: p.status
    },
    project: {
      name: p.project_name,
      project_type: p.project_type,
      location_city: p.location_city,
      property_area_m2: p.property_area_m2
    },
    moodboard: p.moodboard_data || null,
    render: p.render_data || null,
    acceptance: {
      accepted_at: p.accepted_at,
      accepted_via: p.accepted_via,
      is_decided: !!p.accepted_at,
      can_decide: !p.accepted_at
    },
    public_token_expires_at: p.public_token_expires_at
  },
  meta: { request_id: sess.request_id }
}}];
